const number = root.querySelector('[data-number]');
number.dataset.number = '12847';
window.SyntariNumbers.set(number, 12847);

const number = root.querySelector('[data-number]');
number.dataset.number = '0';
window.SyntariNumbers.set(number, 0);

const input = root.querySelector('.invalid');
input.value = 'syntari-studio';
input.classList.remove('invalid');
input.removeAttribute('aria-invalid');
root.querySelector('.error').hidden = true;

root.querySelector('.ring strong').textContent = '100';
root.querySelector('.ring').setAttribute('aria-label', 'Experience score: 100 out of 100');
root.querySelector('.performance-copy h3').textContent = 'Perfect';
const progress = root.querySelector('.progress');
if (progress) { progress.setAttribute('aria-valuenow', '100'); progress.firstElementChild.style.width = '100%'; }

const input = root.querySelector('input');
input.value = input.min;
input.dispatchEvent(new Event('input', { bubbles: true }));

const input = root.querySelector('input');
input.value = input.max;
input.dispatchEvent(new Event('input', { bubbles: true }));

const search = root.querySelector('input[type="search"]');
search.value = 'No matching project';
search.dispatchEvent(new Event('input', { bubbles: true }));

root.querySelectorAll('.agent-tasks li').forEach(row => { row.className = 'is-complete'; row.querySelector('small').textContent = 'Completed'; row.querySelector('.task-percent').textContent = '100%'; row.querySelector('.task-mark').innerHTML = window.SyntariIcon('circlecheck'); });
root.querySelector('[data-todo-count]').textContent = '4 of 4 completed';
root.querySelector('[data-run-status]').textContent = 'All tasks completed';
root.querySelector('[data-agent-action="todo-run"]').textContent = 'Replay';

const inputs = [...root.querySelectorAll('input[type="range"]')];
inputs[0].value = inputs[0].min; inputs[1].value = inputs[1].max;
inputs.forEach(input => input.dispatchEvent(new Event('input', { bubbles: true })));
